from functools import cmp_to_key


def _parse(version):
    """Parse a semantic version string into comparable components."""
    # Build metadata is ignored for precedence and may itself contain '+'.
    main = version.split('+', 1)[0]

    if '-' in main:
        core, prerelease = main.split('-', 1)
        prerelease_parts = prerelease.split('.')
    else:
        core = main
        prerelease_parts = []

    major, minor, patch = (int(part) for part in core.split('.'))
    return major, minor, patch, prerelease_parts


def _compare_prerelease(a_parts, b_parts):
    """Compare two pre-release identifier lists according to SemVer 2.0.0."""
    for a, b in zip(a_parts, b_parts):
        a_numeric = a.isdigit()
        b_numeric = b.isdigit()

        if a_numeric and b_numeric:
            a_val, b_val = int(a), int(b)
            if a_val < b_val:
                return -1
            if a_val > b_val:
                return 1
        elif a_numeric != b_numeric:
            # Numeric identifiers always have lower precedence than
            # alphanumeric identifiers.
            return -1 if a_numeric else 1
        else:
            if a < b:
                return -1
            if a > b:
                return 1

    if len(a_parts) < len(b_parts):
        return -1
    if len(a_parts) > len(b_parts):
        return 1
    return 0


def _compare_versions(a, b):
    a_major, a_minor, a_patch, a_pre = _parse(a)
    b_major, b_minor, b_patch, b_pre = _parse(b)

    a_core = (a_major, a_minor, a_patch)
    b_core = (b_major, b_minor, b_patch)
    if a_core < b_core:
        return -1
    if a_core > b_core:
        return 1

    # A version without a pre-release has higher precedence than one with.
    if not a_pre and not b_pre:
        return 0
    if not a_pre:
        return 1
    if not b_pre:
        return -1

    return _compare_prerelease(a_pre, b_pre)


def sort_versions(vs):
    """Return versions sorted by SemVer 2.0.0 precedence, lowest first."""
    return sorted(vs, key=cmp_to_key(_compare_versions))
